"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[9053],{4458(e,n,t){t.r(n),t.d(n,{assets:()=>p,contentTitle:()=>d,default:()=>c,frontMatter:()=>l,metadata:()=>a,toc:()=>h});const a=JSON.parse('{"id":"part5-deep-learning-and-llms/index","title":"Part V \u2014 Deep Learning & LLMs","description":"From the single neuron all the way to modern LLM alignment. Feed\u2011forward networks (concepts, then training/debugging), CNNs (theory then PyTorch), forecasting, autoregressive baselines, RNNs with a step-by-step transl...","source":"@site/docs/part5-deep-learning-and-llms/index.mdx","sourceDirName":"part5-deep-learning-and-llms","slug":"/part5-deep-learning-and-llms/overview","permalink":"/tutorials/part5-deep-learning-and-llms/overview","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"frontMatter":{"title":"Part V \u2014 Deep Learning & LLMs","slug":"/part5-deep-learning-and-llms/overview","description":"From the single neuron all the way to modern LLM alignment. Feed\u2011forward networks (concepts, then training/debugging), CNNs (theory then PyTorch), forecasting, autoregressive baselines, RNNs with a step-by-step transl...","sidebar_label":"Part overview","pagination_label":"Part overview","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"5. Trees, bagging, and boosting","permalink":"/tutorials/part4-ml-foundations/05-trees-bagging-boosting"},"next":{"title":"1. Feed-forward network concepts","permalink":"/tutorials/part5-deep-learning-and-llms/01-ffn-concepts"}}');var r=t(4848),i=t(8453),o=t(8172);const s=JSON.parse('{"sourcePath":"part5-deep-learning-and-llms/index.html","route":"/part5-deep-learning-and-llms/overview","kind":"part","partId":"part5","partLabel":"Part V - Deep Learning & Large Language Models","accent":"coral","heading":"Part V \u2014 Deep Learning & LLMs","title":"Part V \u2014 Deep Learning & LLMs","description":"From the single neuron all the way to modern LLM alignment. Feed\u2011forward networks (concepts, then training/debugging), CNNs (theory then PyTorch), forecasting, autoregressive baselines, RNNs with a step-by-step transl...","readingMinutes":2,"bodyClass":"","normalizeMath":false,"toc":[{"id":"concept-map","label":"Concept Map"},{"id":"chapters-in-order","label":"Chapters in order"}],"html":"<p>From the single neuron all the way to modern LLM alignment. Feed\u2011forward\\nnetworks (concepts, then training/debugging), CNNs (theory then PyTorch),\\nforecasting, autoregressive baselines, RNNs with a step-by-step translation example, then <strong>Transformers &amp; attention</strong>\\nas the bridge from cross-attention to self-attention and GPT-style generation, followed by <strong>modern LLM alignment</strong>\\nbeyond DPO.</p>\\n\\n<div class=\\"tr-note\\">\\n  <strong>Prerequisites</strong>\\n  <a href=\\"/tutorials/part4-ml-foundations/overview\\">Part IV</a> end\u2011to\u2011end. You\\n  should be comfortable with the PyTorch training loop, autograd, loss\\n  functions, and the geometric view of a linear model before starting here.\\n</div>\\n\\n<div class=\\"tr-tip\\">\\n  <strong>How the chapters cluster</strong>\\n  <ul>\\n    <li><strong>FFN track</strong> \u2014 Chapters 1, 2 (Chapter 3 is the single-chapter reference version).</li>\\n    <li><strong>CNN track</strong> \u2014 Chapters 4, 5, 6; Chapter 7 is the dropout/train-eval deep dive that expands the short dropout section in Chapter 6.</li>\\n    <li><strong>Sequence track</strong> \u2014 Chapters 8, 9, 10: sequence data, AR baselines, recurrent hidden state, language/speech/forecasting use cases, GRU/LSTM gates, and seq2seq translation. The animated RNN companion gives a live narrated walkthrough before the formal RNN chapter.</li>\\n    <li><strong>LLM track</strong> \u2014 Chapters 11, 12, 13: attention mechanics, decoder-only generation, fine-tuning, and alignment.</li>\\n  </ul>\\n</div>\\n\\n<div class=\\"tr-warn\\">\\n  <strong>About chapter 3 (optional reference edition)</strong>\\n  Chapter 3 is a publication\u2011style reference version of\\n  Chapters 1 and 2, with the same theory in a single reference form. <strong>If you\\n  read 1 and 2 in order, skip Chapter 3</strong> \u2014 it repeats the same\\n  material. Use it as a single\u2011document reference if you ever want one\\n  long FFN article instead of the split lecture form.\\n</div>\\n\\n<h2 id=\\"concept-map\\">Concept Map</h2>\\n<table>\\n  <thead>\\n    <tr>\\n      <th>Cluster</th>\\n      <th>Primary chapters</th>\\n      <th>How the related chapters should be read</th>\\n    </tr>\\n  </thead>\\n  <tbody>\\n    <tr>\\n      <td>Feed-forward neural networks</td>\\n      <td><a href=\\"/tutorials/part5-deep-learning-and-llms/01-ffn-concepts\\">Ch. 1</a> and <a href=\\"/tutorials/part5-deep-learning-and-llms/02-ffn-training-debugging\\">Ch. 2</a></td>\\n      <td><a href=\\"/tutorials/part5-deep-learning-and-llms/03-ffn-canonical-merged\\">Ch. 3</a> is the optional single-chapter reference edition, not a required third lecture.</td>\\n    </tr>\\n    <tr>\\n      <td>CNNs</td>\\n      <td><a href=\\"/tutorials/part5-deep-learning-and-llms/04-cnn-convolution\\">Ch. 4</a>, <a href=\\"/tutorials/part5-deep-learning-and-llms/05-cnn-architecture\\">Ch. 5</a>, <a href=\\"/tutorials/part5-deep-learning-and-llms/06-cnn-pytorch-implementation\\">Ch. 6</a></td>\\n      <td><a href=\\"/tutorials/part5-deep-learning-and-llms/07-cnn-dropout-train-eval\\">Ch. 7</a> expands the dropout/train-eval subsection from Ch. 6 into a full deep dive.</td>\\n    </tr>\\n    <tr>\\n      <td>Sequence forecasting</td>\\n      <td><a href=\\"/tutorials/part5-deep-learning-and-llms/08-forecasting-sequence-data\\">Ch. 8</a></td>\\n      <td>Ch. 9 implements the AR baseline, Ch. 10 moves from recurrent hidden state into GRU/LSTM memory and encoder-decoder translation, and Ch. 11 turns that bridge into cross-attention, self-attention, and causal GPT generation.</td>\\n    </tr>\\n    <tr>\\n      <td>LLM adaptation and alignment</td>\\n      <td><a href=\\"/tutorials/part5-deep-learning-and-llms/12-llm-fine-tuning\\">Ch. 12</a> and <a href=\\"/tutorials/part5-deep-learning-and-llms/13-modern-llm-alignment-orpo-grpo\\">Ch. 13</a></td>\\n      <td>Ch. 12 owns SFT/PEFT/fine-tuning and introduces DPO/RLHF. Ch. 13 owns the modern ORPO/KTO/GRPO/RLAIF comparison.</td>\\n    </tr>\\n  </tbody>\\n</table>\\n\\n<h2 id=\\"chapters-in-order\\">Chapters in order</h2>\\n<ol>\\n  <li><a href=\\"/tutorials/part5-deep-learning-and-llms/01-ffn-concepts\\">Feed\u2011forward neural networks: concepts</a></li>\\n  <li><a href=\\"/tutorials/part5-deep-learning-and-llms/02-ffn-training-debugging\\">Feed\u2011forward neural networks: training &amp; debugging</a></li>\\n  <li><a href=\\"/tutorials/part5-deep-learning-and-llms/03-ffn-canonical-merged\\"><em>(Optional reference)</em> FFN single-chapter reference</a></li>\\n  <li><a href=\\"/tutorials/part5-deep-learning-and-llms/04-cnn-convolution\\">CNN \u2014 convolution</a></li>\\n  <li><a href=\\"/tutorials/part5-deep-learning-and-llms/05-cnn-architecture\\">CNN \u2014 architecture</a></li>\\n  <li><a href=\\"/tutorials/part5-deep-learning-and-llms/06-cnn-pytorch-implementation\\">CNN \u2014 PyTorch implementation</a></li>\\n  <li><a href=\\"/tutorials/part5-deep-learning-and-llms/07-cnn-dropout-train-eval\\">CNN \u2014 dropout &amp; train/eval</a></li>\\n  <li><a href=\\"/tutorials/part5-deep-learning-and-llms/08-forecasting-sequence-data\\">Forecasting &amp; sequence data</a></li>\\n  <li><a href=\\"/tutorials/part5-deep-learning-and-llms/09-autoregressive-linear-model\\">Autoregressive linear model</a></li>\\n  <li><a href=\\"/tutorials/labs/rnn\\"><em>Companion lab:</em> animated RNN walkthrough for words, memory, prediction, and training</a></li>\\n  <li><a href=\\"/tutorials/part5-deep-learning-and-llms/10-recurrent-neural-networks\\">Recurrent neural networks</a></li>\\n  <li><a href=\\"/tutorials/part5-deep-learning-and-llms/11-transformers-and-attention\\">Transformers &amp; attention</a></li>\\n  <li><a href=\\"/tutorials/part5-deep-learning-and-llms/12-llm-fine-tuning\\">LLM fine\u2011tuning &amp; optimization (covers SFT, PEFT/LoRA/QLoRA, DPO, classic RLHF)</a></li>\\n  <li><a href=\\"/tutorials/part5-deep-learning-and-llms/13-modern-llm-alignment-orpo-grpo\\">Modern LLM alignment: ORPO, GRPO, KTO, RLAIF</a></li>\\n</ol>\\n\\n<div class=\\"tr-note\\">\\n  <strong>About the LLM track (Ch. 11\u201313)</strong>\\n  Chapter 11 explains the Transformer architecture itself. Chapter 12 covers\\n  how to <em>adapt</em> a pretrained Transformer to your domain (SFT, LoRA,\\n  QLoRA), then introduces evaluation and first-generation alignment methods\\n  such as DPO/RLHF. Chapter 13 is the alignment continuation: it starts\\n  with a DPO recap only to compare ORPO, KTO, GRPO, RLAIF, and PPO-style RLHF\\n  in one decision framework. Read the repeated ideas as \u201cintro here,\\n  comparison there.\u201d\\n</div>"}'),l={title:"Part V \u2014 Deep Learning & LLMs",slug:"/part5-deep-learning-and-llms/overview",description:"From the single neuron all the way to modern LLM alignment. Feed\u2011forward networks (concepts, then training/debugging), CNNs (theory then PyTorch), forecasting, autoregressive baselines, RNNs with a step-by-step transl...",sidebar_label:"Part overview",pagination_label:"Part overview",hide_title:!0,hide_table_of_contents:!0},d=void 0,p={},h=[];function g(e){return(0,r.jsx)(o.A,{content:s})}function c(e={}){const{wrapper:n}={...(0,i.R)(),...e.components};return n?(0,r.jsx)(n,{...e,children:(0,r.jsx)(g,{...e})}):g()}}}]);